function filterMachines(e){let t=0;Array.from(document.getElementById("post-list").children).forEach(n=>{const s=n.querySelector("a"),o=s.parentElement.nextElementSibling??s;s.textContent.toLowerCase().includes(e.toLowerCase())||o.textContent.toLowerCase().includes(e.toLowerCase())?(n.classList.remove("dn"),t++):n.classList.add("dn")}),document.getElementById("post-count").textContent=t}window.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("post-search");if(!e)return;e.addEventListener("input",()=>{filterMachines(e.value)})})